window.mountCanvasNavigation=async function(owner){
 const icons=await fetch('data:application/json;base64,').then(r=>r.json());const colors=['#8C77AC','#5E9693','#BA8C65','#AC7393','#8B9D62','#B59A58'];const backgrounds=['#F0EDF6','#EAF3F1','#F7F0E9','#F8EDF2','#EFF3E9','#F8F3E6'];
 const nav=document.createElement('aside');nav.className='cn-sidebar nl-ui';const library=document.createElement('section');library.className='cn-library nl-ui';library.hidden=true;owner.vp.current.append(nav,library);owner.vp.current.classList.add('cn-with-sidebar');
 let query='',sort='updated',iconTarget=null;const assigned={};const esc=t=>owner.esc(t);const svg=c=>icons[assigned[c.id]??(owner.CV.indexOf(c)*7+2)%icons.length].svg;
 const openCanvas=id=>{library.hidden=true;owner.goCanvas(id);renderNav();};
 function renderNav(){nav.innerHTML='<header><b>notlinear</b><button title="Collapse sidebar" data-collapse><i class="ti ti-layout-sidebar-left-collapse"></i></button></header><div class="cn-primary"><button data-search><i class="ti ti-search"></i>Search<kbd>⌘K</kbd></button><button class="cn-new" data-new><i class="ti ti-edit"></i>New chat<kbd>⌘N</kbd></button></div><div class="cn-nav-scroll"><details><summary>Projects <i class="ti ti-layout-grid"></i><span>＋</span></summary><p class="cn-hint">Your project spaces</p></details><div class="cn-canvas-heading"><button data-library><i class="ti ti-chevron-down"></i> CANVASES <span>'+owner.CV.length+'</span></button><button data-new title="New canvas">＋</button></div><div class="cn-canvas-list">'+owner.CV.map((c,i)=>'<button class="cn-canvas-row '+(c.id===owner.cv()&&!library.hidden?'':c.id===owner.cv()?'active':'')+'" data-canvas="'+c.id+'"><span class="cn-icon" style="color:'+colors[i%6]+'">'+svg(c)+'</span><span>'+esc(c.name)+'</span></button>').join('')+'<button class="cn-show-all" data-library>View all canvases ↗</button></div><details><summary>Threads</summary><button class="cn-simple" data-current>Flow Sketch conversation</button></details><details><summary>Notes <span>＋</span></summary><button class="cn-simple" data-note>Create a note</button></details><details><summary>Recent branches</summary><button class="cn-simple" data-branches>Browse current branches</button></details></div><footer><span class="cn-user">Y</span><b>Yash</b><button title="Canvas settings" data-settings><i class="ti ti-settings"></i></button></footer>';
 nav.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>{library.hidden=false;renderLibrary();});nav.querySelectorAll('[data-new]').forEach(b=>b.onclick=newCanvas);nav.querySelectorAll('[data-canvas]').forEach(b=>b.onclick=()=>openCanvas(b.dataset.canvas));nav.querySelector('[data-search]').onclick=()=>owner.openSearch();nav.querySelector('[data-current]').onclick=()=>{library.hidden=true;owner.goCanvas('flow');};nav.querySelector('[data-note]').onclick=()=>{library.hidden=true;owner.runCmd('note');};nav.querySelector('[data-branches]').onclick=()=>{library.hidden=true;owner.showAll=true;owner.draw();owner.fit();};nav.querySelector('[data-settings]').onclick=()=>{library.hidden=true;owner.contextIslands.navigate();};nav.querySelector('[data-collapse]').onclick=()=>{owner.vp.current.classList.toggle('cn-nav-collapsed');};}
 function newCanvas(){owner.newCanvas();library.hidden=true;renderNav();}
 function renderLibrary(){const list=owner.CV.filter(c=>c.name.toLowerCase().includes(query.toLowerCase()));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));library.innerHTML='<header><div><span class="cn-library-glyph"><i class="ti ti-layout-grid"></i></span><div><h1>Canvases</h1><p>'+owner.CV.length+' canvases · Your space to think freely</p></div></div><button class="cn-create" data-create>＋ New canvas</button></header><div class="cn-library-filters"><label><i class="ti ti-search"></i><input aria-label="Search canvases" placeholder="Search canvases…" value="'+esc(query)+'"></label><select aria-label="Sort canvases"><option value="updated">Last updated</option><option value="name" '+(sort==='name'?'selected':'')+'>Name</option></select><button data-close title="Back to canvas">×</button></div><div class="cn-library-grid">'+list.map((c,i)=>'<article class="cn-tile" style="background:'+backgrounds[i%6]+'"><button class="cn-tile-open" data-open="'+c.id+'"><h2>'+esc(c.name)+'</h2><p>'+esc(c.id==='flow'?'A connected conversation about product ideas.':c.meta)+'</p><small>'+(c.id==='flow'?'3 conversations':'Start a conversation')+' · '+esc(c.meta)+'</small><span class="cn-tile-art" style="color:'+colors[i%6]+'">'+svg(c)+'</span></button><button class="cn-change-icon" data-icon="'+c.id+'" title="Change canvas icon"><i class="ti ti-palette"></i></button></article>').join('')+(list.length?'':'<div class="cn-empty">No canvases found. Try another search.</div>')+'</div>';
 library.querySelector('input').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;renderLibrary();const input=library.querySelector('input');input.focus();input.setSelectionRange(pos,pos);};library.querySelector('select').onchange=e=>{sort=e.target.value;renderLibrary();};library.querySelector('[data-create]').onclick=newCanvas;library.querySelector('[data-close]').onclick=()=>library.hidden=true;library.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openCanvas(b.dataset.open));library.querySelectorAll('[data-icon]').forEach(b=>b.onclick=()=>pickIcon(b.dataset.icon));}
 function pickIcon(id){owner.vp.current.querySelectorAll('.cn-icon-scrim').forEach(n=>n.remove());iconTarget=id;const picker=document.createElement('div');picker.className='cn-icon-scrim nl-ui';picker.innerHTML='<section role="dialog" aria-label="Choose a Mind Garden icon"><header><div><h2>Mind Garden</h2><p>Choose a canvas icon</p></div><button title="Close icon picker">×</button></header><input aria-label="Search icons" placeholder="Search flowers, leaves, stars…"><div class="cn-icon-grid"></div></section>';const draw=filter=>{picker.querySelector('.cn-icon-grid').innerHTML=icons.map((x,i)=>({x,i})).filter(({x})=>x.name.toLowerCase().includes(filter.toLowerCase())).map(({x,i})=>'<button data-pick="'+i+'" title="'+x.name+'">'+x.svg+'</button>').join('');picker.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{assigned[iconTarget]=Number(b.dataset.pick);picker.remove();renderNav();renderLibrary();});};draw('');picker.querySelector('input').oninput=e=>draw(e.target.value);const closePicker=()=>{picker.remove();document.removeEventListener('keydown',onEscape);};const onEscape=e=>{if(e.key==='Escape'){e.preventDefault();closePicker();}};picker.querySelector('header button').onclick=e=>{e.stopPropagation();closePicker();};picker.addEventListener('pointerdown',e=>{if(e.target===picker)closePicker();});document.addEventListener('keydown',onEscape);owner.vp.current.appendChild(picker);picker.querySelector('input').focus();}
 const reopen=document.createElement('button');reopen.className='cn-reopen nl-ui';reopen.title='Open sidebar';reopen.innerHTML='<i class="ti ti-layout-sidebar-left-expand"></i>';reopen.onclick=()=>owner.vp.current.classList.remove('cn-nav-collapsed');owner.vp.current.appendChild(reopen);
 const fit=owner.fit.bind(owner);owner.fit=()=>{fit();if(!owner.vp.current.classList.contains('cn-nav-collapsed')){owner.v[owner.key()].x+=118;owner.apply();}};
 renderNav();return{refresh:renderNav};
};
